from pathlib import Path
p=Path(__file__).parent/'templates'; p.mkdir(exist_ok=True)
templates={
'base.html':'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QualityLite</title><link rel="stylesheet" href="{{url_for('static',filename='style.css')}}"><script defer src="{{url_for('static',filename='app.js')}}"></script></head><body><aside><a class="brand" href="/">Q<span>QualityLite<small>CALIDAD E INOCUIDAD</small></span></a><nav><a href="/">Inicio</a>{% if g.user %}{% if allowed('company',true) %}<a href="/company">Empresa</a>{% endif %}{% for key,label in modules.items() %}<a href="/m/{{key}}">{{label}}</a>{% endfor %}<a href="/evidence">Evidencias</a><a href="/reports">Reportes</a>{% if allowed('users',true) %}<a href="/users">Usuarios</a><a href="/settings">Configuración</a><a href="/backups">Respaldos</a><a href="/events">Historial</a>{% endif %}<a href="/password">Cambiar contraseña</a>{% endif %}</nav><footer>Gestión local · Versión 0.1</footer></aside><main><header><span>Sistema de gestión / QualityLite</span>{% if g.user %}<form action="/logout" method="post"><input type="hidden" name="_csrf" value="{{csrf()}}">{{g.user.name}} · {{g.user.role}} <button>Salir</button></form>{% endif %}</header>{% for message in get_flashed_messages() %}<div class="notice">{{message}}</div>{% endfor %}{% block content %}{% endblock %}</main></body></html>''',
'login.html':'''{% extends 'base.html' %}{% block content %}<section class="narrow"><p class="eyebrow">BIENVENIDO</p><h1>Acceso al sistema</h1><p>Documentos, registros y evidencias en un solo lugar.</p><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><label>Usuario<input name="username" required autocomplete="username"></label><label>Contraseña<input name="password" type="password" required autocomplete="current-password"></label><button class="primary">Iniciar sesión</button></form></section>{% endblock %}''',
'setup.html':'''{% extends 'base.html' %}{% block content %}<p class="eyebrow">CONFIGURACIÓN INICIAL</p><h1>Prepare su empresa</h1><p>Abra esta página desde el servidor. El token está en <code>{{token_path}}</code>.</p><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><section><h2>1. Empresa y alcance</h2><div class="grid">{% for k in ['razon_social','nombre_comercial','rfc','domicilio','telefono','email','responsable_calidad','responsable_inocuidad','giro','productos','alcance','normas','areas'] %}<label>{{k|replace('_',' ')|capitalize}}<input name="{{k}}" {% if k=='razon_social' %}required{% endif %}></label>{% endfor %}</div></section><section><h2>2. Superusuario</h2><div class="grid"><label>Usuario<input name="username" required></label><label>Nombre completo<input name="nombre" required></label><label>Contraseña (12 caracteres mínimo)<input name="password" type="password" minlength="12" required></label><label>Confirmación<input name="confirm" type="password" required></label></div></section><section><h2>3. Finalizar</h2><p>La escucha inicial es local. Después configure IP y puerto en Configuración; cree usuarios con los roles Calidad, Auditor y Visor en Usuarios.</p><label>Token local de instalación<input name="token" required></label><button class="primary">Guardar empresa y crear superusuario</button></section></form>{% endblock %}''',
'home.html':'''{% extends 'base.html' %}{% block content %}<p class="eyebrow">VISTA GENERAL</p><h1>Todo listo para mejorar.</h1><p>{{company.get('razon_social','')}} · Calidad e inocuidad</p><div class="cards">{% for k,v in counts.items() %}<a class="card" href="/m/{{k}}"><span>{{modules[k]}}</span><strong>{{v}}</strong><small>Consultar módulo →</small></a>{% endfor %}</div><section><h2>Un sistema, evidencia verificable</h2><p>Cree formatos propios, capture registros y conserve sus evidencias. Los documentos requieren revisión y aprobación antes de entrar en vigor.</p><p>Las plantillas y auditorías internas requieren validación de su empresa. Esta herramienta no otorga certificación.</p></section>{% endblock %}''',
'listing.html':'''{% extends 'base.html' %}{% block content %}<div class="heading"><div><p class="eyebrow">GESTIÓN</p><h1>{{modules[module]}}</h1></div>{% if allowed(module,true) %}<a class="button primary" href="/m/{{module}}/new">+ Crear</a>{% endif %}</div><section><form class="inline"><input name="q" value="{{q}}" placeholder="Buscar código, título, área, proceso o responsable"><button>Buscar</button></form><div class="actions"><a href="/export/{{module}}/pdf">Exportar PDF</a><a href="/export/{{module}}/xlsx">Exportar Excel</a></div><table><thead><tr><th>Código</th><th>Título</th><th>Versión</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>{% for r in rows %}<tr><td><a href="/item/{{r.id}}">{{r.code}}</a></td><td>{{r.title}}</td><td>{{r.version}}</td><td><span class="badge">{{r.state}}</span></td><td>{{r.created[:10]}}</td></tr>{% else %}<tr><td colspan="5">No hay registros. Cree el primero para comenzar.</td></tr>{% endfor %}</tbody></table></section>{% endblock %}''',
'edit.html':'''{% extends 'base.html' %}{% block content %}<p class="eyebrow">{{modules[module]}}</p><h1>Crear {{ 'registro' if module=='records' else 'elemento' }}</h1>{% if module=='records' and not form %}<section><h2>Seleccione un formato vigente</h2>{% for f in forms %}<p><a href="?form_id={{f.id}}">{{f.code}} · {{f.title}} · v{{f.version}}</a></p>{% else %}<p>Primero cree, revise y apruebe un formato.</p>{% endfor %}</section>{% else %}<form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{csrf()}}"><section>{% if module=='records' %}<input type="hidden" name="form_id" value="{{form.id}}"><h2>{{form.title}} · v{{form.version}}</h2><p>{{loads(form.data).get('instrucciones','')}}</p>{% for f in loads(form.data).schema %}<label>{{f.label}} {% if f.required %}*{% endif %}{% if f.type in ['fotografia','archivo','evidencia'] %}<input type="file" name="{{f.id}}" {% if f.required %}required{% endif %}>{% elif f.type in ['lista','multiple','si_no_na'] %}<select name="{{f.id}}" {% if f.type=='multiple' %}multiple{% endif %} {% if f.required %}required{% endif %}>{% for o in (['Sí','No','No aplica'] if f.type=='si_no_na' else f.options) %}<option>{{o}}</option>{% endfor %}</select>{% elif f.type in ['texto_largo','tabla','comentarios','observaciones'] %}<textarea name="{{f.id}}" {% if f.required %}required{% endif %} placeholder="{{'Una fila por línea; columnas separadas por |' if f.type=='tabla' else ''}}"></textarea>{% else %}<input name="{{f.id}}" type="{{ {'fecha':'date','hora':'time','numero':'number','casilla':'checkbox'}.get(f.type,'text') }}" {% if f.type=='numero' %}step="any"{% endif %} {% if f.required %}required{% endif %}>{% endif %}</label>{% endfor %}{% else %}<div class="grid">{% for k in fields[module] %}<label>{{k|replace('_',' ')|capitalize}}<input name="{{k}}" {% if k in ['codigo','titulo'] %}required{% endif %} {% if k.startswith('fecha') or k=='proxima_revision' %}type="date"{% endif %}></label>{% endfor %}</div>{% endif %}</section>{% if module=='forms' %}<section><h2>Campos del formato</h2><p>Configure campos, opciones y evidencias sin programar. Las tablas se capturan como filas de texto; responsable es una identificación, no firma electrónica.</p><div id="designer"></div><button type="button" id="add-field">+ Agregar campo</button><template id="field-template"><div class="fieldrow"><input name="label" placeholder="Nombre del campo"><select name="type">{% for t in types %}<option value="{{t}}">{{t}}</option>{% endfor %}</select><select name="required"><option value="no">Opcional</option><option value="si">Obligatorio</option></select><input name="options" placeholder="Opciones separadas por coma"><button type="button" class="remove-field">Quitar</button></div></template></section>{% endif %}{% if module!='records' %}<section><label>Adjunto / evidencia<input type="file" name="adjunto" multiple></label></section>{% endif %}<button class="primary">Guardar borrador</button></form>{% endif %}{% endblock %}''',
'detail.html':'''{% extends 'base.html' %}{% block content %}<p class="eyebrow">{{modules[row.module]}} / {{row.code}}</p><div class="heading"><h1>{{row.title}}</h1><a class="button" href="/item/{{row.id}}/pdf">Descargar PDF</a></div><p><span class="badge">{{row.state}}</span> Versión {{row.version}} · Folio {{row.code}} · Responsable ID {{row.owner}}</p><section><h2>Información</h2>{% for k,v in data.items() %}{% if k not in ['schema','answers'] %}<p><b>{{k|replace('_',' ')|capitalize}}:</b> {{v}}</p>{% endif %}{% endfor %}{% for f in data.get('schema',[]) %}<p><b>{{f.label}}:</b> {{data.get('answers',{}).get(f.id,'Ver evidencias')}}</p>{% endfor %}</section><section><h2>Evidencias y documentos</h2>{% for f in files %}<p><a href="/file/{{f.id}}">{{f.name}}</a> · Campo {{f.field}} · {{f.created[:19]}} · Usuario {{f.owner}}<small class="hash">SHA-256 {{f.sha256}}</small></p>{% else %}<p>Sin adjuntos.</p>{% endfor %}{% if allowed(row.module,true) and row.state not in ['cerrado','vigente','aprobado','obsoleto'] %}<form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{csrf()}}"><input type="hidden" name="op" value="upload">{% for f in data.get('schema',[]) if f.type in ['archivo','fotografia','evidencia'] %}<label>{{f.label}}<input type="file" name="{{f.id}}"></label>{% endfor %}<label>Adjuntos generales<input type="file" name="adjunto" multiple></label><button>Adjuntar</button></form>{% endif %}</section>{% if allowed(row.module,true) %}{% if row.state=='borrador' and row.module!='records' %}<section><h2>Editar borrador</h2><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><input type="hidden" name="op" value="edit"><div class="grid">{% for k in fields.get(row.module,[]) %}<label>{{k|replace('_',' ')}}<input name="{{k}}" value="{{data.get(k,'')}}"></label>{% endfor %}</div><button>Guardar cambios</button></form></section>{% endif %}<section><h2>Flujo y control</h2>{% if row.state not in ['cerrado','obsoleto'] %}<form method="post" class="inline"><input type="hidden" name="_csrf" value="{{csrf()}}"><input type="hidden" name="op" value="state"><select name="state">{% for s in (['en revisión','pendiente de aprobación','aprobado','vigente','obsoleto','borrador'] if row.module in ['documents','forms'] else ['cerrado']) %}<option>{{s}}</option>{% endfor %}</select><button>Aplicar estado</button></form>{% endif %}{% if row.module in ['documents','forms'] and row.state in ['aprobado','vigente'] %}<h3>Nueva versión</h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="{{csrf()}}"><input type="hidden" name="op" value="revision"><label>Motivo del cambio<input name="motivo" required></label><label>Nuevo título<input name="titulo" value="{{row.title}}"></label><label>Archivo de la nueva versión<input type="file" name="adjunto"></label><button>Crear borrador de nueva versión</button></form>{% endif %}</section>{% endif %}<section><h2>Historial verificable</h2>{% for e in events %}<p>{{e.created}} · Usuario {{e.user}} · {{e.action}} · {{e.detail}}</p>{% endfor %}</section>{% endblock %}''',
'company.html':'''{% extends 'base.html' %}{% block content %}<h1>Empresa</h1><section><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><div class="grid">{% for k,v in values.items() %}<label>{{k|replace('_',' ')|capitalize}}<input name="{{k}}" value="{{v}}"></label>{% endfor %}</div><button class="primary">Guardar empresa</button></form></section>{% endblock %}''',
'users.html':'''{% extends 'base.html' %}{% block content %}<h1>Usuarios y roles</h1><section><table><tr><th>Usuario</th><th>Nombre</th><th>Rol</th></tr>{% for r in rows %}<tr><td>{{r.username}}</td><td>{{r.name}}</td><td>{{r.role}}</td></tr>{% endfor %}</table></section><section><h2>Alta de usuario</h2><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><div class="grid">{% for k,l in [('username','Usuario'),('name','Nombre'),('email','Correo'),('password','Contraseña temporal (mínimo 12 caracteres)')] %}<label>{{l}}<input name="{{k}}" required {% if k=='password' %}type="password" minlength="12"{% endif %}></label>{% endfor %}<label>Rol<select name="role">{% for r in roles %}<option>{{r}}</option>{% endfor %}</select></label></div><button class="primary">Crear usuario</button></form></section>{% endblock %}''',
'settings.html':'''{% extends 'base.html' %}{% block content %}<h1>Configuración de red</h1><section><p>Acceso actual: {{'local' if request.remote_addr in ['127.0.0.1','::1'] else 'desde la red'}}. Servidor: {{request.host}}.</p><p>HTTP debe usarse únicamente en una red interna de confianza. Para otras redes configure HTTPS mediante un proxy seguro.</p><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><label>Nombre<input name="name" value="{{cfg.name}}"></label><label>Escuchar en IPv4<select name="host">{% for ip in ips+['0.0.0.0'] %}<option {% if ip==cfg.host %}selected{% endif %}>{{ip}}</option>{% endfor %}</select></label><p>0.0.0.0 autoriza escuchar en todas las interfaces IPv4.</p><label>Puerto<input type="number" min="1024" max="65535" name="port" value="{{cfg.port}}" required></label><label>Carpeta adicional de respaldos<input name="backup_dir" value="{{backup_dir}}"></label><label><input type="checkbox" name="backup_daily" {% if backup_daily %}checked{% endif %}> Crear respaldo cada 24 horas</label><button class="primary">Guardar configuración</button></form><p>URL: http://{{cfg.host if cfg.host!='0.0.0.0' else 'IP-DEL-SERVIDOR'}}:{{cfg.port}}</p><p>Use el acceso directo Administrar servicio para aplicar el firewall y reiniciar.</p></section>{% endblock %}''',
'backups.html':'''{% extends 'base.html' %}{% block content %}<h1>Respaldos</h1><section><p>Último respaldo: {{last}}</p><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}"><button class="primary">Crear respaldo completo</button></form><p>Descargue las copias y consérvelas en otro dispositivo. La restauración se realiza localmente con el servicio detenido; consulte el manual.</p>{% for name in rows %}<p><a href="/backup/{{name}}">{{name}}</a></p>{% endfor %}</section>{% endblock %}''',
'events.html':'''{% extends 'base.html' %}{% block content %}<h1>Historial de actividad</h1><section><table><tr><th>Fecha</th><th>Usuario</th><th>Operación</th><th>Elemento</th><th>Detalle</th></tr>{% for r in rows %}<tr><td>{{r.created}}</td><td>{{r.user}}</td><td>{{r.action}}</td><td>{{r.item}}</td><td>{{r.detail}}</td></tr>{% endfor %}</table></section>{% endblock %}''',
'reports.html':'''{% extends 'base.html' %}{% block content %}<h1>Reportes</h1><section><p>Exportaciones de los módulos con estado, responsable, fechas y datos completos.</p><table><tr><th>Módulo</th><th>PDF</th><th>Excel</th></tr>{% for k,v in modules.items() %}<tr><td>{{v}}</td><td><a href="/export/{{k}}/pdf">Descargar</a></td><td><a href="/export/{{k}}/xlsx">Descargar</a></td></tr>{% endfor %}</table></section>{% endblock %}''',
'evidence.html':'''{% extends 'base.html' %}{% block content %}<h1>Evidencias</h1><section><table><tr><th>Archivo</th><th>Registro</th><th>Campo</th><th>Usuario</th><th>Fecha</th></tr>{% for r in rows %}<tr><td><a href="/file/{{r.id}}">{{r.name}}</a></td><td><a href="/item/{{r.item}}">{{r.title}}</a></td><td>{{r.field}}</td><td>{{r.owner}}</td><td>{{r.created[:19]}}</td></tr>{% endfor %}</table></section>{% endblock %}''',
'password.html':'''{% extends 'base.html' %}{% block content %}<h1>Cambiar contraseña</h1><section><form method="post"><input type="hidden" name="_csrf" value="{{csrf()}}">{% for k,l in [('current','Contraseña actual'),('password','Nueva contraseña (12 caracteres mínimo)'),('confirm','Confirmar nueva contraseña')] %}<label>{{l}}<input name="{{k}}" type="password" required></label>{% endfor %}<button class="primary">Actualizar contraseña</button></form></section>{% endblock %}''',
'error.html':'''{% extends 'base.html' %}{% block content %}<section><h1>No se pudo completar la operación</h1><p>{{error}}</p><a href="/">Volver al inicio</a></section>{% endblock %}'''
}
for name,content in templates.items(): (p/name).write_text(content,encoding='utf-8')
s=Path(__file__).parent/'static'; s.mkdir(exist_ok=True)
(s/'style.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#1e3045;font:15px "Segoe UI",Arial,sans-serif}aside{width:242px;background:#112c3b;color:#c1d2db;position:fixed;inset:0 auto 0 0;overflow:auto;padding:28px 18px}.brand{display:flex;gap:12px;color:white;font-size:32px;font-weight:750;text-decoration:none;margin:0 4px 32px}.brand span{font-size:21px}.brand small{display:block;font-size:9px;letter-spacing:2px;margin-top:5px;color:#8ac7bf}nav a{display:block;color:#bed0d9;padding:10px 15px;border-radius:7px;text-decoration:none;font-size:14px}nav a:hover{background:#214454;color:white}footer{font-size:11px;padding:28px 15px;color:#8aa1ad}main{margin-left:242px;padding:0 40px 40px;max-width:1600px}header{display:flex;justify-content:space-between;align-items:center;min-height:80px;border-bottom:1px solid #e1e7ed;margin-bottom:36px;font-size:12px;color:#697c8f}header form{display:flex;align-items:center;gap:12px}h1{font-size:32px;letter-spacing:-1px;margin:8px 0 14px}h2{font-size:20px;margin-top:0}p{line-height:1.65}.eyebrow{font-size:11px;letter-spacing:2px;color:#16877e;font-weight:700}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:28px 0}.card,section{background:#fff;border:1px solid #e0e7ed;border-radius:12px;padding:26px;margin-bottom:20px;box-shadow:0 3px 8px #112c3b03}.card{text-decoration:none;color:inherit;margin:0;display:flex;flex-direction:column;gap:18px}.card strong{font-size:40px}.card small{color:#19877b}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:block;font-size:13px;font-weight:600;margin-bottom:16px}input,textarea,select{display:block;width:100%;padding:11px 12px;border:1px solid #cbd6e0;border-radius:6px;font:inherit;background:white;color:#243b50;margin-top:6px}input[type=checkbox]{width:auto}textarea{min-height:95px}button,.button{display:inline-block;border:1px solid #c8d4dd;border-radius:6px;padding:10px 17px;background:#fff;color:#26475c;font:600 13px "Segoe UI";cursor:pointer;text-decoration:none}.primary{background:#147d72;color:#fff;border-color:#147d72}a{color:#137f78}.heading,.inline,.actions{display:flex;align-items:center;gap:14px;justify-content:space-between}.inline input{margin:0}.actions{justify-content:flex-end;margin:16px 0;font-size:12px}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;background:#f5f8fa;color:#6a7e8c;font-size:11px;text-transform:uppercase;letter-spacing:.6px}th,td{padding:14px 10px;border-bottom:1px solid #e9edf2}.badge{background:#e4f3ef;color:#167c6b;border-radius:12px;padding:4px 9px;font-size:11px}.notice{padding:15px;background:#e0f3ec;border-radius:8px;margin-bottom:20px}.narrow{max-width:540px;margin:60px auto}.fieldrow{display:grid;grid-template-columns:2fr 1fr 1fr 2fr auto;gap:8px;margin:12px 0}.hash{display:block;color:#7a8e9a;word-break:break-all;font-size:10px}code{word-break:break-all}@media(max-width:900px){aside{position:static;width:auto}nav{display:flex;flex-wrap:wrap}.brand{margin-bottom:15px}footer{display:none}main{margin-left:0;padding:0 18px 24px}.cards,.grid{grid-template-columns:1fr 1fr}.fieldrow{grid-template-columns:1fr 1fr}section{overflow:auto}header{flex-wrap:wrap}}@media(max-width:560px){.cards,.grid{grid-template-columns:1fr}h1{font-size:26px}}''',encoding='utf-8')
(s/'app.js').write_text('''const add=document.getElementById('add-field');if(add){const append=()=>{const row=document.getElementById('field-template').content.cloneNode(true);row.querySelector('.remove-field').addEventListener('click',e=>e.target.closest('.fieldrow').remove());document.getElementById('designer').append(row)};add.addEventListener('click',append);append();}''',encoding='utf-8')
